import{_ as e,o as l,c as o,a8 as i}from"./chunks/framework.CiGKN4gy.js";const p=JSON.parse('{"title":"最新版（Current）","description":"","frontmatter":{"title":"最新版（Current）","lang":"zh-CN"},"headers":[],"relativePath":"zh-cn/changes/current.md","filePath":"zh-cn/changes/current.md","lastUpdated":1790354326000}'),r={name:"zh-cn/changes/current.md"};function t(c,a,d,h,n,u){return l(),o("div",{"data-pagefind-body":!0,"data-pagefind-meta":"base64:JTdCJTIydGl0bGUlMjIlM0ElMjIlRTYlOUMlODAlRTYlOTYlQjAlRTclODklODglRUYlQkMlODhDdXJyZW50JUVGJUJDJTg5JTIyJTJDJTIybGFuZyUyMiUzQSUyMnpoLUNOJTIyJTJDJTIyZGF0ZSUyMiUzQTE3OTAzNTQzMjYwMDAlN0Q="},[...a[0]||(a[0]=[i('<h1 id="更新日志-current" tabindex="-1">更新日志（Current） <a class="header-anchor" href="#更新日志-current" aria-label="Permalink to &quot;更新日志（Current）&quot;">​</a></h1><p>本文件的格式基于<a href="https://keepachangelog.com/zh-CN/1.0.0" target="_blank" rel="noreferrer">如何维护更新日志</a>， 并且本项目遵守<a href="https://semver.org/lang/zh-CN/spec/v2.0.0.html" target="_blank" rel="noreferrer">语义化版本</a>。</p><div class="tip custom-block"><p class="custom-block-title">何为「不兼容的修改」？</p><ul><li>原有的配置文件可能无法使用，比如删除或者重命名了某个配置项。</li></ul></div><h2 id="未发布" tabindex="-1">[未发布] <a class="header-anchor" href="#未发布" aria-label="Permalink to &quot;[未发布]&quot;">​</a></h2><h3 id="新增" tabindex="-1">新增 <a class="header-anchor" href="#新增" aria-label="Permalink to &quot;新增&quot;">​</a></h3><h3 id="移除" tabindex="-1">移除 <a class="header-anchor" href="#移除" aria-label="Permalink to &quot;移除&quot;">​</a></h3><h3 id="变动" tabindex="-1">变动 <a class="header-anchor" href="#变动" aria-label="Permalink to &quot;变动&quot;">​</a></h3><h3 id="修复" tabindex="-1">修复 <a class="header-anchor" href="#修复" aria-label="Permalink to &quot;修复&quot;">​</a></h3><hr><h2 id="_10-1-2-2022-07-09-utc-0800" tabindex="-1">[10.1.2] - 2022-07-09 UTC+0800 <a class="header-anchor" href="#_10-1-2-2022-07-09-utc-0800" aria-label="Permalink to &quot;[10.1.2] - 2022-07-09 UTC+0800&quot;">​</a></h2><h3 id="修复-1" tabindex="-1">修复 <a class="header-anchor" href="#修复-1" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>兼容 <code>nginx-1.23.0</code>。</li></ul><hr><h2 id="_10-1-1-2022-01-07-utc-0800" tabindex="-1">[10.1.1] - 2022-01-07 UTC+0800 <a class="header-anchor" href="#_10-1-1-2022-01-07-utc-0800" aria-label="Permalink to &quot;[10.1.1] - 2022-01-07 UTC+0800&quot;">​</a></h2><h3 id="新增-1" tabindex="-1">新增 <a class="header-anchor" href="#新增-1" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li>支持 PCRE2。</li></ul><h3 id="修复-2" tabindex="-1">修复 <a class="header-anchor" href="#修复-2" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li><p>内存泄漏。</p></li><li><p>验证码和 Under Attack Mode（五秒盾）有时会无限刷新。</p></li></ul><hr><h2 id="_10-1-0-2021-12-14-utc-0800" tabindex="-1">[10.1.0] - 2021-12-14 UTC+0800 <a class="header-anchor" href="#_10-1-0-2021-12-14-utc-0800" aria-label="Permalink to &quot;[10.1.0] - 2021-12-14 UTC+0800&quot;">​</a></h2><h3 id="新增-2" tabindex="-1">新增 <a class="header-anchor" href="#新增-2" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li><p>指令 <code>waf</code> 可以设置为 <code>bypass</code> 模式，即仅检测并记录日志，但不会拦截任何请求。</p></li><li><p>指令 <code>waf_verify_bot</code> 新增了参数 <code>SogouSpider</code>，用于验证是否为搜狗爬虫。</p></li></ul><h3 id="修复-3" tabindex="-1">修复 <a class="header-anchor" href="#修复-3" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li><p>内存回收机制并未正常运行，这虽然不会造成内存泄漏，但会导致内存占用居高不下，并引发性能问题。</p></li><li><p>友好爬虫验证功能会错误地打印拦截日志。</p></li></ul><hr><h2 id="_10-0-1-2021-12-05-utc-0800" tabindex="-1">[10.0.1] - 2021-12-05 UTC+0800 <a class="header-anchor" href="#_10-0-1-2021-12-05-utc-0800" aria-label="Permalink to &quot;[10.0.1] - 2021-12-05 UTC+0800&quot;">​</a></h2><h3 id="新增-3" tabindex="-1">新增 <a class="header-anchor" href="#新增-3" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li>添加了两个彩蛋，你可以在文档中找到相关的线索。这两个彩蛋不会自动触发，所以不会影响正常使用。</li></ul><h3 id="修复-4" tabindex="-1">修复 <a class="header-anchor" href="#修复-4" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>指令 <code>waf_mode</code> 中所有与请求方法对应的参数均失效。</li></ul><hr><h2 id="_10-0-0-2021-11-30-utc-0800" tabindex="-1">[10.0.0] - 2021-11-30 UTC+0800 <a class="header-anchor" href="#_10-0-0-2021-11-30-utc-0800" aria-label="Permalink to &quot;[10.0.0] - 2021-11-30 UTC+0800&quot;">​</a></h2><h3 id="新增-4" tabindex="-1">新增 <a class="header-anchor" href="#新增-4" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li><p>新指令 <code>waf_zone</code>，用来声明一块共享内存，这块内存将被用于其他的指令，比如 <code>waf_cc_deny</code>。</p></li><li><p>新指令 <code>waf_action</code>，用于设置拦截请求后的动作，比如返回特定的状态码或者使用验证码对客户端做人机认证。</p></li><li><p>新指令 <code>waf_block_page</code>，用于设置拦截页面，当请求被拦截后将指定的 HTML 文件返回。</p></li><li><p>新内置变量 <code>$waf_rate</code>，用来表示一个统计周期内当前 IP 的访问次数。统计周期由指令 <code>waf_cc_deny</code> 的参数 <code>rate</code> 决定，如果 IP 已经被拉黑，则由参数 <code>duration</code> 决定。</p></li><li><p>指令 <code>waf_captcha</code> 增加了一个参数 <code>max_fails</code>，用来设置验证码最大试错次数和超出后的拉黑时间。</p></li><li><p>指令 <code>waf_captcha</code> 增加了一个参数 <code>zone</code>，用来指定一块共享内存，当且仅当设置了参数 <code>max_fails</code> 时才需要设置。</p></li><li><p>指令 <code>waf_captcha</code> 增加了一个参数 <code>sitekey</code>，当且仅当省略了参数 <code>file</code> 时才需要设置。</p></li><li><p>当你重载 nginx 时，模块会尽可能地保留共享内存中的信息，使其不被清空，比如 CC 防护的拉黑列表。</p></li></ul><h3 id="移除-1" tabindex="-1">移除 <a class="header-anchor" href="#移除-1" aria-label="Permalink to &quot;移除&quot;">​</a></h3><ul><li><p>移除了指令 <code>waf_http_status</code>，相关的功能合并到指令 <code>waf_action</code>。</p></li><li><p>移除了指令 <code>waf_cc_deny</code> 的参数 <code>size</code>，现在使用 <code>zone</code> 代替。</p></li></ul><h3 id="变动-1" tabindex="-1">变动 <a class="header-anchor" href="#变动-1" aria-label="Permalink to &quot;变动&quot;">​</a></h3><ul><li><p>允许省略指令 <code>waf_under_attack</code> 的参数 <code>file</code>，省略此参数时将使用一个内置的文件，它来自 <code>assets/under_attack.html</code>。</p></li><li><p>允许省略指令 <code>waf_captcha</code> 的参数 <code>file</code>，省略此参数时将根据参数 <code>prov</code> 的值使用一个内置的文件，这些文件来自目录 <code>assets/</code>。</p></li><li><p>更多的调试日志。</p></li></ul><hr><h2 id="_9-0-6-2021-10-10-utc-0800" tabindex="-1">[9.0.6] - 2021-10-10 UTC+0800 <a class="header-anchor" href="#_9-0-6-2021-10-10-utc-0800" aria-label="Permalink to &quot;[9.0.6] - 2021-10-10 UTC+0800&quot;">​</a></h2><h3 id="修复-5" tabindex="-1">修复 <a class="header-anchor" href="#修复-5" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>当指令 <code>try_files</code> 生效时无法完成 CAPTCHA 的验证。</li></ul><hr><h2 id="_9-0-5-2021-10-09-utc-0800" tabindex="-1">[9.0.5] - 2021-10-09 UTC+0800 <a class="header-anchor" href="#_9-0-5-2021-10-09-utc-0800" aria-label="Permalink to &quot;[9.0.5] - 2021-10-09 UTC+0800&quot;">​</a></h2><h3 id="新的测试套件" tabindex="-1">新的测试套件 <a class="header-anchor" href="#新的测试套件" aria-label="Permalink to &quot;新的测试套件&quot;">​</a></h3><p>偶然间看到了一个测试套件：<a href="https://github.com/openresty/test-nginx" target="_blank" rel="noreferrer">test-nginx</a>。 看完之后感觉很好便拿来测试，编了不少测试用例，果不其然发现了一大堆 Bug，不愧是我。</p><h3 id="变动-2" tabindex="-1">变动 <a class="header-anchor" href="#变动-2" aria-label="Permalink to &quot;变动&quot;">​</a></h3><ul><li><p>删除了无用的调试日志。</p></li><li><p>更多的调试日志。</p></li></ul><h3 id="修复-6" tabindex="-1">修复 <a class="header-anchor" href="#修复-6" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li><p>有时连接会被过早地关闭。</p></li><li><p>启用 CAPTCHA 后请求体的检测结果可能会出错。</p></li><li><p>CAPTCHA 可能会因为 HTTP 缓存而失败。</p></li><li><p>重载 nginx 时存在内存泄露。</p></li><li><p>未能正确合并上层配置块的 <code>waf_cache</code> 指令。</p></li><li><p>未能正确合并上层配置块的 <code>waf_cc_deny</code> 指令。</p></li><li><p>未能正确继承上层配置块的 Referer 黑名单。</p></li><li><p>未能正确识别一些错误的配置。</p></li><li><p>修复了一条默认的 URL 黑名单规则。</p></li><li><p>修复了下列文件，使得验证码完成后可以自动刷新网页。</p><ul><li><code>assets/hCaptcha.html</code></li><li><code>assets/reCAPTCHAv2_Checkbox.html</code></li><li><code>assets/reCAPTCHAv2_Invisible.html</code></li><li><code>assets/reCAPTCHAv3.html</code></li></ul></li></ul><hr><h2 id="_9-0-4-2021-09-29-utc-0800" tabindex="-1">[9.0.4] - 2021-09-29 UTC+0800 <a class="header-anchor" href="#_9-0-4-2021-09-29-utc-0800" aria-label="Permalink to &quot;[9.0.4] - 2021-09-29 UTC+0800&quot;">​</a></h2><h3 id="修复-7" tabindex="-1">修复 <a class="header-anchor" href="#修复-7" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>当指令 <code>rewrite</code> 造成内部重定向时会错误地跳过所有检测。</li></ul><hr><h2 id="_9-0-3-2021-09-28-utc-0800" tabindex="-1">[9.0.3] - 2021-09-28 UTC+0800 <a class="header-anchor" href="#_9-0-3-2021-09-28-utc-0800" aria-label="Permalink to &quot;[9.0.3] - 2021-09-28 UTC+0800&quot;">​</a></h2><h3 id="变动-3" tabindex="-1">变动 <a class="header-anchor" href="#变动-3" aria-label="Permalink to &quot;变动&quot;">​</a></h3><ul><li>更多的调试日志。</li></ul><h3 id="修复-8" tabindex="-1">修复 <a class="header-anchor" href="#修复-8" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>验证码页面不能正常显示。</li></ul><hr><h2 id="_9-0-2-2021-09-25-utc-0800" tabindex="-1">[9.0.2] - 2021-09-25 UTC+0800 <a class="header-anchor" href="#_9-0-2-2021-09-25-utc-0800" aria-label="Permalink to &quot;[9.0.2] - 2021-09-25 UTC+0800&quot;">​</a></h2><h3 id="修复-9" tabindex="-1">修复 <a class="header-anchor" href="#修复-9" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>内置变量 <code>$waf_blocking_log</code> 的值有时会出错。</li></ul><hr><h2 id="_9-0-1-2021-09-24-utc-0800" tabindex="-1">[9.0.1] - 2021-09-24 UTC+0800 <a class="header-anchor" href="#_9-0-1-2021-09-24-utc-0800" aria-label="Permalink to &quot;[9.0.1] - 2021-09-24 UTC+0800&quot;">​</a></h2><h3 id="修复-10" tabindex="-1">修复 <a class="header-anchor" href="#修复-10" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>未能正确读取 ModSecurity 的规则。</li></ul><hr><h2 id="_9-0-0-2021-09-23-utc-0800" tabindex="-1">[9.0.0] - 2021-09-23 UTC+0800 <a class="header-anchor" href="#_9-0-0-2021-09-23-utc-0800" aria-label="Permalink to &quot;[9.0.0] - 2021-09-23 UTC+0800&quot;">​</a></h2><h3 id="注意" tabindex="-1"><strong>注意</strong> <a class="header-anchor" href="#注意" aria-label="Permalink to &quot;**注意**&quot;">​</a></h3><p>如果您想要升级到此版本，请查看文档中的跨版本升级的指南。</p><h3 id="新增-5" tabindex="-1">新增 <a class="header-anchor" href="#新增-5" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li><p>兼容了<a href="https://github.com/SpiderLabs/ModSecurity" target="_blank" rel="noreferrer">ModSecurity</a> 的规则。</p></li><li><p>增加了两个指令：<code>waf_modsecurity</code> 和 <code>waf_modsecurity_transaction_id</code>。</p></li><li><p>为指令 <code>waf_priority</code> 增加了参数 <code>MODSECURITY</code>。</p></li></ul><h3 id="移除-2" tabindex="-1">移除 <a class="header-anchor" href="#移除-2" aria-label="Permalink to &quot;移除&quot;">​</a></h3><ul><li><p>删除了指令 <code>waf_mode</code> 的一些参数：<code>LIBINJECTION</code>、<code>LIBINJECTION-SQLI</code>、<code>LIBINJECTION-XSS</code> 和 <code>ADV</code>。</p></li><li><p>删除了指令 <code>waf_priority</code> 的参数 <code>ADV</code>。</p></li><li><p>删除了依赖 <a href="https://github.com/libinjection/libinjection" target="_blank" rel="noreferrer">libinjection</a>。</p></li></ul><h3 id="修复-11" tabindex="-1">修复 <a class="header-anchor" href="#修复-11" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li><p>当验证码通过时不再返回 404 状态码，而是返回 204 状态码。</p></li><li><p>有时不会完整地检查请求体。</p></li></ul><hr><h2 id="_8-0-3-2021-08-27-utc-0800" tabindex="-1">[8.0.3] - 2021-08-27 UTC+0800 <a class="header-anchor" href="#_8-0-3-2021-08-27-utc-0800" aria-label="Permalink to &quot;[8.0.3] - 2021-08-27 UTC+0800&quot;">​</a></h2><h3 id="修复-12" tabindex="-1">修复 <a class="header-anchor" href="#修复-12" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li><p>内存泄露</p></li><li><p>一个没有初始化的结构体字段，会导致错误日志中出现大量的 <code>malloc(size) failed (12: Out of memory)</code>。</p></li></ul><hr><h2 id="_8-0-2-2021-08-27-utc-0800" tabindex="-1">[8.0.2] - 2021-08-27 UTC+0800 <a class="header-anchor" href="#_8-0-2-2021-08-27-utc-0800" aria-label="Permalink to &quot;[8.0.2] - 2021-08-27 UTC+0800&quot;">​</a></h2><h3 id="修复-13" tabindex="-1">修复 <a class="header-anchor" href="#修复-13" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li><p>开启验证码后 nginx 崩溃（段错误），原因是未能正确合并不同级别的 <code>waf_captcha</code> 指令。</p></li><li><p>不能显示验证码页面，原因是未能正确合并不同级别的 <code>waf_captcha</code> 指令。</p></li><li><p>如果使用了 <code>proxy_pass</code> 指令，Under-Attack-Mode 和验证码均不能正常工作。</p></li></ul><hr><h2 id="_8-0-1-2021-08-23-utc-0800" tabindex="-1">[8.0.1] - 2021-08-23 UTC+0800 <a class="header-anchor" href="#_8-0-1-2021-08-23-utc-0800" aria-label="Permalink to &quot;[8.0.1] - 2021-08-23 UTC+0800&quot;">​</a></h2><h3 id="新增-6" tabindex="-1">新增 <a class="header-anchor" href="#新增-6" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li>当 CC 防护返回 444 状态码时不再生成额外的响应头。</li></ul><h3 id="修复-14" tabindex="-1">修复 <a class="header-anchor" href="#修复-14" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li><p>当 <code>User-Agent</code> 为空时会引发段错误。</p></li><li><p>不能正确合并指令 <code>waf_http_status</code>。</p></li></ul><hr><h2 id="_8-0-0-2021-08-21-utc-0800" tabindex="-1">[8.0.0] - 2021-08-21 UTC+0800 <a class="header-anchor" href="#_8-0-0-2021-08-21-utc-0800" aria-label="Permalink to &quot;[8.0.0] - 2021-08-21 UTC+0800&quot;">​</a></h2><h3 id="注意-1" tabindex="-1"><strong>注意</strong> <a class="header-anchor" href="#注意-1" aria-label="Permalink to &quot;**注意**&quot;">​</a></h3><p>如果您想要升级到此版本，请查看文档中的跨版本升级的指南。</p><h3 id="新增-7" tabindex="-1">新增 <a class="header-anchor" href="#新增-7" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li><p>引入了第三方平台的验证码，支持 hCaptcha、reCAPTCHAv2 和 reCAPTCHAv3，相关的指令为 <code>waf_captcha</code>。</p></li><li><p>支持识别友好爬虫，包括 GooleBot、BingBot、BaiduSpider 和 YandexBot，识别成功后自动放行，相关的指令为 <code>waf_verify_bot</code>。</p></li><li><p>CC 防护支持开启验证码模式，开启后当请求频率超出限制后会启用验证码，如果连续三次验证失败则拉黑 IP，反之则重新统计请求频率。</p></li></ul><h3 id="变动-4" tabindex="-1">变动 <a class="header-anchor" href="#变动-4" aria-label="Permalink to &quot;变动&quot;">​</a></h3><ul><li><p>指令 <code>waf_mode</code> 的语法有所变化，详见文档中的跨版本升级的指南。</p></li><li><p>指令 <code>waf_cc_deny</code> 的语法有所变化，详见文档中的跨版本升级的指南。</p></li><li><p>指令 <code>waf_cache</code> 的语法有所变化，详见文档中的跨版本升级的指南。</p></li><li><p>支持修改「请求体检查」的优先级。</p></li></ul><h3 id="移除-3" tabindex="-1">移除 <a class="header-anchor" href="#移除-3" aria-label="Permalink to &quot;移除&quot;">​</a></h3><ul><li>移除了指令 <code>waf_cache</code> 的两个参数，分别是 <code>interval</code> 和 <code>percent</code>。</li></ul><hr><h2 id="_7-1-0-2021-08-16-utc-0800" tabindex="-1">[7.1.0] - 2021-08-16 UTC+0800 <a class="header-anchor" href="#_7-1-0-2021-08-16-utc-0800" aria-label="Permalink to &quot;[7.1.0] - 2021-08-16 UTC+0800&quot;">​</a></h2><h3 id="新增-8" tabindex="-1">新增 <a class="header-anchor" href="#新增-8" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li>配置项 <code>waf_cc_deny</code> 的参数 <code>rate</code> 允许更多个格式，如 <code>500r/s</code>、<code>500r/60s</code>、<code>500r/m</code>、<code>500r/60m</code>、<code>500r/h</code>、<code>500r/60h</code> 和 <code>500r/d</code>。</li></ul><hr><h2 id="_7-0-1-2021-08-11-utc-0800" tabindex="-1">[7.0.1] - 2021-08-11 UTC+0800 <a class="header-anchor" href="#_7-0-1-2021-08-11-utc-0800" aria-label="Permalink to &quot;[7.0.1] - 2021-08-11 UTC+0800&quot;">​</a></h2><h3 id="修复-15" tabindex="-1">修复 <a class="header-anchor" href="#修复-15" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li><p>不能正确解析 IP 黑白名单中的 <code>0.0.0.0/0</code>。</p></li><li><p>兼容不支持 IPV6 的运行环境。</p></li></ul><hr><h2 id="_7-0-0-2021-08-04-utc-0800" tabindex="-1">[7.0.0] - 2021-08-04 UTC+0800 <a class="header-anchor" href="#_7-0-0-2021-08-04-utc-0800" aria-label="Permalink to &quot;[7.0.0] - 2021-08-04 UTC+0800&quot;">​</a></h2><h3 id="变动-5" tabindex="-1">变动 <a class="header-anchor" href="#变动-5" aria-label="Permalink to &quot;变动&quot;">​</a></h3><ul><li><p>改变了 Under Attack Mode 的实现方式。不再使用重定向实现，而是通过修改响应体实现。</p></li><li><p>删除了配置项 <code>waf_under_attack</code> 的参数 <code>uri</code>，详情见文档。</p></li><li><p>为配置项 <code>waf_under_attack</code> 增加了一个参数 <code>file</code>，该参数的值应该是一个 HTML 文件的绝对路径，详情见文档。</p></li><li><p>不允许在 <code>http</code> 这一级中使用配置项 <code>waf_cc_deny</code>。</p></li></ul>',114)])])}const b=e(r,[["render",t]]);export{p as __pageData,b as default};
